+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+      color: var(--accent);
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(1.75rem, 5vw, 2.2rem);
+      line-height: 1.1;
+    }
+
+    .intro {
+      margin: 12px 0 0;
+      color: var(--text-muted);
+      line-height: 1.6;
+    }
+
+    form {
+      margin-top: 28px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid rgba(148, 163, 184, 0.28);
+      border-radius: 16px;
+      background: rgba(248, 250, 252, 0.95);
+    }
+
+    .checkbox-row {
+      display: flex;
+      gap: 14px;
+      align-items: flex-start;
+    }
+
+    input[type="checkbox"] {
+      width: 20px;
+      height: 20px;
+      margin: 2px 0 0;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      margin: 0;
+      color: var(--text-muted);
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .actions {
+      margin-top: 22px;
+    }
+
+    button {
+      width: 100%;
+      border: 0;
+      border-radius: 14px;
+      padding: 14px 18px;
+      font: inherit;
+      font-weight: 700;
+      color: #ffffff;
