 <body>
   <main class="shell">
     <section class="card" aria-labelledby="consent-title">
       <p class="eyebrow">Account setup</p>
       <h1 id="consent-title">Confirm your consent</h1>
       <p class="intro">Please review and accept the terms of use before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="terms-consent"
               name="terms-consent"
               type="checkbox"
               required
               aria-describedby="terms-helper"
             >
             <label for="terms-consent">I agree to the terms of use.</label>
           </div>
           <p id="terms-helper" class="helper-text">Required to finish setup and submit the form.</p>
         </div>

         <div class="actions">
           <button type="submit">Submit</button>
         </div>

         <p id="form-status" class="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("consent-form");
     const checkbox = document.getElementById("terms-consent");
     const status = document.getElementById("form-status");

     function syncCheckboxMessage() {
       checkbox.setCustomValidity(
         checkbox.checked ? "" : "Please agree to the terms of use before submitting."
       );
     }

     checkbox.addEventListener("change", () => {
       syncCheckboxMessage();
       status.textContent = "";
       status.dataset.state = "";
     });

     form.addEventListener("submit", (event) => {
       syncCheckboxMessage();

       if (!form.checkValidity()) {
         event.preventDefault();
         form.reportValidity();
         return;
       }

       event.preventDefault();
       status.textContent = "Consent recorded. Your form is ready to move forward.";
       status.dataset.state = "success";
       form.reset();
       syncCheckboxMessage();
     });

     syncCheckboxMessage();
   </script>
